const expandedLearningBank=[];
for(const [track,rows] of Object.entries(platformAdditions)){for(const [index,row] of rows.trim().split('\n').entries()){const [topic,q,a,points]=row.split('|');if(!topic||!q||!a||!points)throw Error('Invalid expanded question');expandedLearningBank.push({id:`expanded-${track}-${index}`,track,topic,q,a,points:points.split(';'),source:learningSources[track]});}}
